QJsonObject v2Face() {
  return {{"referenceVersion", "V2"},
          {"bodyId", 11},
          {"provenance",
           QJsonObject{
               {"featureId", 23},
               {"kind", "Face"},
               {"operation", "Generated"},
               {"role", "Custom"},
               {"localName", "result"},
               {"instanceKey",
                QJsonObject{{"featureId", 23}, {"slot", 1}}},
               {"origins",
                QJsonArray{QJsonObject{
                    {"featureId", 22},
                    {"kind", "Face"},
                    {"operation", "Seed"},
                    {"role", "Cap"},
                    {"localName", "seed"},
                    {"instanceKey",
                     QJsonObject{{"featureId", 22}, {"slot", 2}}}}}}}}};
}

QJsonObject v2Edge() {
  auto edge = v2Face();
  auto provenance = edge.value("provenance").toObject();
  provenance.insert("kind", "Edge");
  auto origins = provenance.value("origins").toArray();
  auto origin = origins[0].toObject();
  origin.insert("kind", "Edge");
  origins[0] = origin;
  provenance.insert("origins", origins);
  edge.insert("provenance", provenance);
  return edge;
}

